import re

def extract_pii(text):
    pii_pattern = r"VIN\s*\d{17}|Parking\s*space\s*\d{17}|Vehicle\s*vrm\s*\d{17}|Zipcode\s*\d{5}"
    match = re.search(pii_pattern, text)
    if match:
        return match.group()
    else:
        return None

text = "VIN 05BHMWB78RK026069 Parking space 05BHMWB78RK026069 Vehicle vrm 05BHMWB78RK026069 Zipcode 05BHMWB78RK026069"
pii = extract_pii(text)
if pii:
    print(f"PII: {pii}")
else:
    print("No PII found.")
```"]

